-- Class notes synopsis batch 24: Slippery Elm through Tansy

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Slippery Elm</strong> (marsh root) is a <strong>cooling</strong>, <strong>demulcent</strong>, <strong>lubricant</strong>, and <strong>alterative</strong> herb - William LeSassier: "relaxes the nerves in the lungs"; helps both the Earth and the Lung. First-line demulcent for <strong>hypochlorhydria</strong>; cooling demulcent for <strong>hyperchlorhydria</strong>; GI demulcent - when working with the digestive system, prefer glycerites, honeys, or vinegars over alcohol; powder in honey. For <strong>sore throat</strong>: demulcent for common cold. Demulcent, nourishing, alterative, fiber formula alongside <a href="?herb=22"><strong>Burdock</strong></a> root and <a href="?herb=154"><strong>Rhubarb</strong></a> (good gut impacts). "Strengthen and Repair" formula: <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=45"><strong>Marshmallow</strong></a>, Slippery Elm. Colon Rescue for diarrhea: Slippery Elm, <a href="?herb=45"><strong>Marshmallow</strong></a>, <a href="?herb=85"><strong>Plantain</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>. Traditional African American formula for bitter and digestive support: Slippery Elm combined with <a href="?herb=61"><strong>Mullein</strong></a> leaf. For <strong>chemo support</strong>: digestive demulcent for pain reduction. Alterative for cold and dry constitutions. <strong>Mucilage is damaged by heat - decoction not appropriate when mucilage is the medicine sought.</strong>$$
WHERE id = 92;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Solomon's Seal</strong> is "the indispensable musculoskeletal remedy" (Matt Wood) - a <strong>power herb</strong> that "loosens what's too tight and tightens what's too loose"; specifically acts on <strong>collagen</strong> and <strong>cartilage</strong>; nutritive to <strong>tendons and ligaments</strong>. For <strong>musculoskeletal</strong>: prevents and removes swelling on bone after injury; supportive for <strong>bone spurs</strong>; repetitive use injuries including <strong>carpal tunnel syndrome</strong>; <strong>arthritis</strong> from old injuries; <strong>calcifications</strong> (calcium build-up on bone/joints); muscular and skeletal tensions in general. Use as tincture and decoction - no oil; take a week off every 2 months in long-term use.$$
WHERE id = 1252;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Spearmint</strong> (Mentha spicata) is a <strong>diaphoretic</strong> and <strong>carminative</strong> herb; helpful for <strong>digestive complaints</strong>, gassiness, bloating, and pain. For <strong>PMOS</strong>: daily infusion for 30 days shown to lower testosterone and reduce <strong>hirsutism</strong> (facial hair).$$
WHERE id = 2607;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Spikenard</strong> (Aralia racemosa) is a <strong>bronchodilator</strong> and <strong>antiviral</strong> for <strong>respiratory</strong> conditions; often prepared in syrup form.$$
WHERE id = 2479;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Spilanthes</strong> is an <strong>antimicrobial</strong>, <strong>antifungal</strong>, and <strong>sialogogue</strong> herb; stimulates saliva flow, activating the whole digestive process beginning in the mouth - the bitter flavor is a notable sialogogue. Antimicrobial in wound wash.$$
WHERE id = 2363;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>St. John's Wort</strong> (SJW) is a <strong>neuroprotective</strong>, <strong>anti-inflammatory</strong>, <strong>antidepressant</strong>, <strong>lymphatic</strong>, and <strong>nervine</strong> herb - a light-bearing plant that blooms at the Summer Solstice. For <strong>depression</strong>: specifically for <strong>GI-based depression</strong> (enteric brain/serotonin connection); for depression with sour stomach, sour attitude, dark outlook, and emotional unease; antidepressant for mild to moderate depression; for <strong>seasonal affective disorder</strong> (SAD) - light-bearing plant par excellence; mood stabilization in chemical sensitivity formula (60-100 drops). Serotonin support alongside <a href="?herb=25"><strong>Black Cohosh</strong></a>. Personal adaptogen formula with <a href="?herb=17"><strong>Schizandra</strong></a> and <a href="?herb=14"><strong>Ginseng</strong></a>. For <strong>nerve pain</strong>: neuroprotective, acts on nerve endings; primary herb for <strong>sciatica</strong>; specific for nerve pain taken internally and topically; for <strong>neuritis</strong> (peripheral nerve inflammation causing numbness, tingling, loss of reflex); high doses for long-term chronic pain, especially in viral picture. SJW oil: warming for nerve pain and sore muscles - one of few fresh plant oils (along with <a href="?herb=88"><strong>Chickweed</strong></a>); used in gua sha and for oilination for stress relief. For <strong>burns</strong>: anti-inflammatory, demulcent - applied topically. For <strong>rheumatoid arthritis</strong>: anti-inflammatory; oilination of affected areas, adjacent, and internally. Anti-inflammatory: inhibits prostaglandins; decreases amyloid reactive oxygen species (Alzheimer's connection); anti-inflammatory to the gut; for hot constitution. For <strong>PMOS</strong>: nerve pain and anti-inflammatory protocol alongside <a href="?herb=75"><strong>Meadowsweet</strong></a> and <a href="?herb=25"><strong>Black Cohosh</strong></a>. Helps ease <strong>withdrawal symptoms</strong> (also <a href="?herb=128"><strong>California Poppy</strong></a>). Vulnerary in wound wash. Topically for swimmer's ear alongside <a href="?herb=79"><strong>Witch Hazel</strong></a> and ACV to evaporate water. For <strong>cancer support</strong>: blood cleansing, lymphatic herb, anti-cancer formula 2. Nervine for diarrhea (as long as not contraindicated). <strong>Significant drug interactions at therapeutic doses - contraindicated with SSRIs (serotonin syndrome risk), ayahuasca, oral contraceptives, cardiac drugs, anticancer agents, immunosuppressives, anti-hypertensives, benzodiazepines, HIV medications, anticoagulants, and antifungals. Do not take with medications without clinical consultation.</strong>$$
WHERE id = 81;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Stoneroot</strong> (Collinsonia canadensis) is a <strong>circulatory herb</strong> and <strong>antilithic</strong>. For <strong>veins</strong>: addresses the veins to bring fluid back up to the heart; for <strong>varicose veins</strong> alongside <a href="?herb=62"><strong>Horse Chestnut</strong></a> and Horsebalm. For <strong>gallstones</strong>: antilithic - <strong>caution if stones are large (analgesics may be needed)</strong>. For <strong>infertility</strong>: circulatory herb for sperm health.$$
WHERE id = 182;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Sumac</strong> is a <strong>sour</strong>, <strong>moistening</strong>, <strong>antioxidant</strong>, and <strong>enzymatic</strong> herb good for Wet, Cold, and Dry constitutions. In nutritive tea for <strong>calcium</strong> and <strong>potassium</strong> - supports bones, hair, and teeth; manages inflammation and insulin. Liquifies dried material in the <strong>bowel</strong>. Enzymatic: breaks up <strong>fatty deposits in the urinary system</strong>. <strong>Not recommended if someone is congested.</strong>$$
WHERE id = 2637;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Sweet Orange</strong> (orange peel) is a <strong>warming</strong>, <strong>drying</strong>, <strong>stimulating bitter</strong>, <strong>aromatic</strong>, and <strong>carminative</strong> herb; gets secretions going in upper GI; allows easier absorption in small intestine; reduces load on liver; warming, drying, and relaxing digestive tincture. For <strong>digestion</strong>: warming bitter that stimulates digestive secretions; for rekindling digestive fire alongside <a href="?herb=124"><strong>Ginger</strong></a>, <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=76"><strong>Fennel</strong></a>, <a href="?herb=100"><strong>Coriander</strong></a>, cumin, <a href="?herb=122"><strong>Dandelion</strong></a> root, <a href="?herb=172"><strong>Artichoke</strong></a> leaf; combined with <a href="?herb=76"><strong>Fennel</strong></a> seed as carminatives; in liver tea formula to get secretions going and reduce liver load. Digestive bitters for <strong>perimenopause</strong> alongside <a href="?herb=983"><strong>Blue Vervain</strong></a>, <a href="?herb=172"><strong>Artichoke</strong></a> leaf, and <a href="?herb=102"><strong>Gentian</strong></a>. For <strong>rheumatoid arthritis</strong>: digestive bitter and carminative. For hot constitution: bitter. In herbal broth recipe (2 T dried). Traditional Hibiscus Refresher with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=111"><strong>Clove</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>, <a href="?herb=1652"><strong>Hawthorn</strong></a>. Note on glycerites: from palm/coconut triglycerides; alcohol is constitutionally hot and dry - consider menstruum (broth, animal fats, salt, molasses, vinegar).$$
WHERE id = 748;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Tansy</strong> is an <strong>antimicrobial</strong> herb used in wound wash.$$
WHERE id = 161;
